--
-- Table structure for table `klasifikasi_log`
--

DROP TABLE IF EXISTS `klasifikasi_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `klasifikasi_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `pr_po_data_id` bigint DEFAULT NULL,
  `layer` smallint DEFAULT NULL COMMENT '1=Rule Base, 2=Regex, 3=SVM',
  `method` enum('RULE_BASE','REGEX','SVM') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `berhasil` tinyint(1) DEFAULT NULL,
  `kategori_hasil_id` bigint DEFAULT NULL,
  `confidence_score` decimal(5,4) DEFAULT NULL,
  `processing_time` decimal(10,4) DEFAULT NULL COMMENT 'Waktu proses dalam detik',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `pr_po_data_id` (`pr_po_data_id`),
  KEY `kategori_hasil_id` (`kategori_hasil_id`),
  CONSTRAINT `klasifikasi_log_ibfk_1` FOREIGN KEY (`pr_po_data_id`) REFERENCES `pr_po_data` (`id`),
  CONSTRAINT `klasifikasi_log_ibfk_2` FOREIGN KEY (`kategori_hasil_id`) REFERENCES `kategori` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=213 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

